/**
 * Type representing all valid icon names
 */
export type IconName = (typeof EXPORTED_ICONS)[number];

/**
 * Check if a string is a valid icon name
 */
export function isValidIcon(name: string): name is IconName {
  return EXPORTED_ICONS.includes(name as IconName);
}

/**
 * Get all icons matching a search term
 */
export function searchIcons(term: string): IconName[] {
  const lowerTerm = term.toLowerCase();
  return EXPORTED_ICONS.filter((icon) => icon.toLowerCase().includes(lowerTerm));
}

